// spec: specs/home.md
// seed: tests/seed.provider.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/provider.json') });

test.describe('מסך הבית — יתרה בדולרים לפי שער יציג', () => {
  test('בשורת "היתרה שלך": "≈ $X · שער יציג DD.MM", X ≈ ₪ ÷ שער @iphone @prod-safe (#ed59d3)', async ({ page }) => {
    // 1. /wallet, לחכות ל"היתרה שלך" ולשורת הדולרים
    await page.goto('/wallet');
    await expect(page.getByText('היתרה שלך').first()).toBeVisible();
    const usdRe = /≈\s*\$([\d,]+\.\d{2})\s*·\s*שער יציג\s*(\d{2})\.(\d{2})/;
    const usdLine = page.getByTestId('balance-usd');
    await expect(usdLine).toBeVisible();
    await expect(usdLine).toHaveText(usdRe);

    // 2. לקרוא את הסכום ב-₪ ואת X מהשורה
    const body = await page.locator('body').innerText();
    const after = body.slice(body.indexOf('היתרה שלך'));
    const ils = after.match(/₪\s?([\d,]+(?:\.\d{1,2})?)/);
    expect(ils, 'סכום ב-₪ ליד "היתרה שלך"').not.toBeNull();
    const amountIls = Number(ils![1].replace(/,/g, ''));

    const m = (await usdLine.innerText()).match(usdRe);
    expect(m, 'שורת "≈ $X · שער יציג DD.MM"').not.toBeNull();
    const usd = Number(m![1].replace(/,/g, ''));
    const day = Number(m![2]);
    const month = Number(m![3]);

    // 3. לחשב שער = ₪ / X
    expect(usd).toBeGreaterThan(0);
    const rate = amountIls / usd;
    expect(rate).toBeGreaterThanOrEqual(2.5);
    expect(rate).toBeLessThanOrEqual(4.5);

    // התאריך DD.MM — לא מאוחר מהיום (שעון ישראל)
    const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', day: '2-digit', month: '2-digit' }).formatToParts(new Date());
    const todayDay = Number(parts.find((p) => p.type === 'day')!.value);
    const todayMonth = Number(parts.find((p) => p.type === 'month')!.value);
    expect(month).toBeGreaterThanOrEqual(1);
    expect(month).toBeLessThanOrEqual(12);
    expect(day).toBeGreaterThanOrEqual(1);
    expect(day).toBeLessThanOrEqual(31);
    // שער מדצמבר כשהיום בינואר נחשב תקין
    const isPrevYear = month === 12 && todayMonth === 1;
    expect(isPrevYear || month < todayMonth || (month === todayMonth && day <= todayDay)).toBe(true);
  });
});
